sys_script.script:
// Before Query Business Rule on your task table
(function executeRule(current, previous /*null when async*/) {
    // Restrict to "Trigger Extraction" tasks under "Unstructured Case"
    // current.addQuery('task_type', 'Trigger Extraction');
   // current.addQuery('treasury_case.case_type', 'Unstructured Case');

    // Get allowed group sys_ids from system property
    var allowedGroupsStr = gs.getProperty('x_hsb11_mss_tsd.treasury.allowed_it_support_group_sys_ids', '');
    var allowedGroups = allowedGroupsStr.split(',');

    var userInAllowedGroup = false;
    if (allowedGroups.length > 0) {
        var groupMemberGR = new GlideRecord('sys_user_grmember');
        groupMemberGR.addQuery('user', gs.getUserID());
        groupMemberGR.addQuery('group', 'IN', allowedGroups);
        groupMemberGR.query();
        if (groupMemberGR.next()) {
            userInAllowedGroup = true;
        }
    }

    // If not in allowed group, hide all matching records
    if (!userInAllowedGroup) {
        current.addQuery('sys_id', ''); // No records will match
    }
})(current, previous);
